Translate("ruRU", "the-hinterlands", {
	title = "Внутренние земли",
	sections = {
		{
			title = "Обзор",
			text = [=[Внутренние земли — дикий край зеленых холмов, глухих лесов и высоких утесов, лежащий к северо-востоку от {link:arathi-highlands}Нагорья Арати{/link} и к востоку от {link:hillsbrad-foothills}Предгорий Хилсбрада{/link}. Дорог через них мало, а ферм еще меньше. Тысячи лет они принадлежат лесным {link:trolls}троллям{/link}, чьи храмы и ступенчатые города до сих пор венчают холмы. На скале на дальнем западе стоит {link:aerie-peak}Заоблачный Пик{/link}, дом {link:dwarves}дворф{/link}ов {red:wildhammer-clan}Неистового Молота{/red} и их грифонов. На дальнем юго-востоке, у моря, тролли Сломанного Клыка держат деревню для {link:horde}Орды{/link}. Между ними лежит земля, воюющая сама с собой: три племени троллей, у которых нет ничего общего, кроме крови, сторожка {link:high-elves}высших эльфов{/link} вдали от дома, а на северо-востоке — великое древо, у которого несут стражу зеленые дракониды.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, когда первые тролли начали строить на этих холмах. Известно, что северные леса некогда были частью империи Амани, державы лесных троллей, и что Амани так и не простили {link:high-elves}эльфов{/link}, поселившихся в землях за ними. Разрушенные города Внутренних земель — работа троллей, а их алтари старше любого людского королевства. {link:dwarves}Дворфы{/link} пришли гораздо позже. После Войны Трех Молотов клан Неистового Молота оставил оскверненные чертоги {link:grim-batol}Грим Батола{/link} и устроил новый дом на Заоблачном Пике. Там, в высокогорье троллей, они приручили диких грифонов и научились летать.]=],
		},
		{
			title = "Наши дни",
			text = [=[У Внутренних земель нет единого хозяина. {link:dwarves}Дворфы{/link} Неистового Молота держат {link:aerie-peak}Заоблачный Пик{/link} под началом своего верховного тана {link:falstad-wildhammer}Фалстад{/link}а Неистового Молота. По крови они союзники {link:ironforge}Стальгорна{/link}, но настаивают, что не входят в {link:alliance}Альянс{/link} и что дружбу с ними надо заслужить делами. {link:trolls}Тролли{/link} Сломанного Клыка держат свою деревню на восточном берегу именем Орды и люто ненавидят дворфов Неистового Молота. Тролли {red:vilebranch-trolls}Порочной Ветви{/red} правят югом и северо-востоком из своих храмов. Они едят плоть других троллей и приносят пленников в жертву кровавому богу {link:hakkar}Хаккару{/link}. {link:witherbark-trolls}Сухокожие{/link} держат юго-запад, где служат собственной паучьей богине. Слизни из старого лагеря Орды у Осклизлой скалы расползлись по речным долинам, а волки, совухи и дикие грифоны охотятся на все, что движется.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:dwarves}Дворфы{/link} Неистового Молота.{/b} Они живут на Заоблачном Пике со своими грифонами. Они горды, шумны и яростно независимы, а старые обиды помнят дольше своих сородичей из {link:ironforge}Стальгорн{/link}а.
• {b}{link:trolls}Тролли{/link} Сломанного Клыка.{/b} Лесные тролли Орды; они держат деревню у моря и без пощады бьются с Порочной Ветвью.
• {b}Тролли Порочной Ветви.{/b} Самое большое и самое свирепое племя этого края. Их столица — {link:jintha-alor}Джинта'Алор{/link}, где их жрица готовит жертвы для бога {link:hakkar}Хаккар{/link}а.
• {b}{link:witherbark-trolls}Тролли племени Сухокожих{/link}.{/b} Они обитают в юго-западных деревнях и в {link:shadra-alor}Шадра'Алор{/link}е. Когда-то они сражались на стороне Орды, а потом обратились против нее.
• {b}{link:high-elves}Высшие эльфы{/link} {link:quel-danil-lodge}Кель'Данил{/link}а.{/b} Следопыты и разведчики Высокодолья держат охотничью сторожку на западе, неподалеку от дворфов.
• {b}Зеленые дракониды.{/b} В {link:seradane}Серадан{/link}е на северо-востоке дракониды и дрейки стерегут великое древо и никого к нему не подпускают.]=],
		},
		{
			title = "История",
			text = [=[• {b}Эпоха Амани.{/b} В былые эпохи лесные тролли правили этими холмами как частью великой империи. {link:troll-wars}Войны троллей{/link} сломили их мощь, но тролли никуда не ушли.
• {b}Три Молота.{/b} После войны трех кланов {link:dwarves}дворф{/link}ы Неистового Молота покинули {link:grim-batol}Грим Батол{/link} и осели на Заоблачном Пике. Они стали наездниками на грифонах севера.
• {b}{link:second-war}Вторая война{/link}.{/b} Когда орочья {link:horde}Орда{/link} двинулась на север, тролли Амани под началом вождя {red:zul-jin}Зул'джина{/red} примкнули к ней в надежде сжечь {link:quel-thalas}Кель'Талас{/link}. Дворфы Неистового Молота летали против них за {link:alliance}Альянс{/link}. Орда некоторое время удерживала позиции во Внутренних землях, среди них лагерь у Осклизлой скалы. В конце концов она их оставила.
• {b}Новая Орда.{/b} При вожде {link:thrall}Тралле{/link} Орда снова нашла друзей среди лесных троллей. Племя Сломанного Клыка примкнуло к ней. {link:witherbark-trolls}Сухокожие{/link} сначала сражались рядом с ней, а затем предали ее, и племя Черного Копья в ответ шлет на север мрачные послания.
• {b}Наши дни.{/b} Ныне тролли Сломанного Клыка ждут, когда вернется Зул'джин, Порочная Ветвь кормит своего кровавого бога, а дворфы Заоблачного Пика считают каждого потерянного грифона.]=],
		},
		{
			title = "Предания холмов",
			text = [=[• {link:trolls}Тролли{/link} Сломанного Клыка говорят, что у трех племен троллей Внутренних земель общего только два: они тролли, и они живут во Внутренних землях.
• На Заоблачном Пике пришельца, который назовет {link:dwarves}дворф{/link}ов Неистового Молота «{link:alliance}Альянс{/link}ом», поправят — громко и сразу.
• Старая загадка, найденная далеко отсюда, на берегах Тернистой долины, говорит о сокровище, спрятанном под водой у подножия большого водопада на побережье Внутренних земель.
• Пьяный наездник на грифоне с Заоблачного Пика однажды упал со своего зверя в затонувший храм Атал'ай в {link:swamp-of-sorrows}Болоте Печали{/link} и выжил, чтобы рассказывать эту историю за выпивку.]=],
		},
	},
})

Translate("ruRU", "aerie-peak", {
	title = "Заоблачный Пик",
	sections = {
		{
			title = "Обзор",
			text = [=[Заоблачный Пик — твердыня {link:dwarves}дворф{/link}ов {red:wildhammer-clan}Неистового Молота{/red}, воздвигнутая на скале у западного края Внутренних земель. Ее сердце — Крепость Громового Молота, где держит двор верховный тан, а над нею — большой грифоний питомник, где рождаются, растут и обучаются грифоны клана. В городке есть таверна, кузнецы, кожевники и колодец в самом центре. Это шумное, гордое и суровое место. Чужакам здесь рады, только когда они себя показали, а тролли востока позаботились о том, чтобы ни один дворф Неистового Молота никогда не спал без топора под рукой.]=],
		},
	},
})

Translate("ruRU", "revantusk-village", {
	title = "Деревня Сломанного Клыка",
	aliases = { "Сломанный Клык" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Сломанного Клыка стоит на юго-восточном берегу Внутренних земель, где лес встречается с морем. Это дом троллей Сломанного Клыка, племени лесных троллей на службе {link:horde}Орды{/link}. Хижины на сваях, рыбацкие лодки и насест ветрокрылов теснятся на узкой полосе между утесами и водой. На деревню нападали тролли Порочной Ветви, а волки и грифоны дикого края отняли у нее немало воинов. Ее жители ответили наградами за головы, кровью и длинным списком обид на {link:dwarves}дворф{/link}ов Заоблачного Пика.]=],
		},
	},
})

Translate("ruRU", "quel-danil-lodge", {
	title = "Сторожка Кель'Данил",
	aliases = { "Кель'Данил" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожка Кель'Данил — охотничья сторожка {link:high-elves}высших эльфов{/link}, построенная среди деревьев на западе Внутренних земель, чуть восточнее Заоблачного Пика. Там несут стражу следопыты, разведчики, стрелки и {link:the-night-watch}дозорные{/link} Высокодолья. Они далеко от {link:quel-thalas}Кель'Таласа{/link} и нашли друзей в {link:dwarves}дворф{/link}ах Неистового Молота. {link:trolls}Тролли{/link} этого края — их враги. Тролли Сломанного Клыка видят в эльфах доказательство того, что дворфы заключают новые союзы, а Сухокожих, попавших в руки эльфов, держат в сторожке пленниками.]=],
		},
	},
})

Translate("ruRU", "shindigger-s-camp", {
	title = "Лагерь Выпивохи",
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Выпивохи — маленькая стоянка с бочонками и кострами на западе Внутренних земель, к востоку от Заоблачного Пика и совсем рядом со Сторожкой {link:quel-danil-lodge}Кель'Данил{/link}. Хозяин ее — {link:rhapsody-shindigger}Рапсоди Шиндиггер{/link}, некогда лучший наездник на грифонах во всем питомнике; он сам варит здесь свое питье с тех пор, как {link:dwarves}дворф{/link}ы его отпустили. Пьет он не один. Рядом с ним разбил лагерь {link:high-elves}высший эльф{/link} {link:gilveradin-sunchaser}Гилверадин Ловец Солнца{/link}, который любит хорошее вино превыше всех знамен и королевств.]=],
		},
	},
})

Translate("ruRU", "skulk-rock", {
	title = "Осклизлая скала",
	sections = {
		{
			title = "Обзор",
			text = [=[Осклизлая скала — пещера и разрушенный лагерь в центре Внутренних земель, у истока реки. Когда-то {link:horde}Орда{/link} держала здесь базу, но давно оставила это место. В брошенных ею ящиках до сих пор лежат бутылки Медовой настойки Внутренних земель — напитка, который больше нигде не купить. Теперь руины заполонили зеленые слизи и нефритовые слизни, и рассказывают, что их ведет некий главный слизень. {link:dwarves}Дворфы{/link} Неистового Молота хотят, чтобы это место расчистили, потому что у них на него свои виды. Неподалеку когда-то нашли разбитое странное металлическое устройство {link:gnomes}гном{/link}ской работы.]=],
		},
	},
})

Translate("ruRU", "jintha-alor", {
	title = "Джинта'Алор",
	sections = {
		{
			title = "Обзор",
			text = [=[Джинта'Алор — столица троллей {red:vilebranch-trolls}Порочной Ветви{/red}. Он поднимается на юге Внутренних земель {link:ogres}огр{/link}омным ступенчатым каменным городом, восходящим терраса за террасой к амфитеатру на вершине. Наверху властвует мерзкая жрица {link:vile-priestess-hexx}Хексс{/link} под охраной стражей Аман'заси. По всему городу стоят сосуды с оскверненной кровью, и их темная сила доводит троллей Порочной Ветви до безумия. Сюда приводят пленников, чтобы принести их в жертву богу {link:hakkar}Хаккару{/link}. Близ вершины останков ждут помойная яма, полная слизней, и волчье логово. В пещере за амфитеатром, как говорят, лежит древнее яйцо тех времен, когда тролли правили империями.]=],
		},
	},
})

Translate("ruRU", "the-altar-of-zul", {
	title = "Алтарь Зула",
	sections = {
		{
			title = "Обзор",
			text = [=[Алтарь Зула — храм троллей на западном краю земель Порочной Ветви, к северо-западу от {link:jintha-alor}Джинта'Алор{/link}а. Его ступени поднимаются к высокому алтарю, где тролли Порочной Ветви совершают свои жертвоприношения. За ним присматривают двое хранителей племени — Киага и Морта'гия. Когда пропал молодой грифон Остроклюв, {link:dwarves}дворф{/link}ы Заоблачного Пика боялись, что его унесли сюда. Они испытали облегчение, когда на алтаре его не нашли, потому что знали, что делают там тролли Порочной Ветви.]=],
		},
	},
})

Translate("ruRU", "shadra-alor", {
	title = "Шадра'Алор",
	sections = {
		{
			title = "Обзор",
			text = [=[Шадра'Алор — храм троллей в глубине юго-запада Внутренних земель, во владениях {link:witherbark-trolls}Сухокожих{/link}. Это обитель их паучьей богини {link:shadra}Шадры{/link}, и леса вокруг кишат ее детьми. Сухокожие собирают ее яд и хранят его в бутылях в своих деревнях. В сердце храма стоит алтарь, у которого саму богиню можно вызвать, если произнести ее истинное имя. Возле храма живет изгнанник Атал'ай — жрец, отвергнутый собственным народом и нашедший горький приют среди Сухокожих.]=],
		},
	},
})

Translate("ruRU", "hiri-watha-and-zun-watha", {
	title = "Хири'вата и Зун'вата",
	aliases = { "Хири'вата", "Зун'вата" },
	sections = {
		{
			title = "Обзор",
			text = [=[Хири'вата и Зун'вата — две деревни троллей племени {link:witherbark-trolls}Сухокожих{/link} на юго-западе Внутренних земель. Они меньше храмовых городов Порочной Ветви, но ничуть не менее опасны. В их хижинах стоят клетки для пленников и бутыли с зеленым ядом пауков {link:shadra-alor}Шадра'Алор{/link}а. Сухокожие когда-то сражались на стороне Орды, а потом предали ее, и {link:darkspear-trolls}племя Черного Копья{/link} из Тернистой долины этого не забыло. Их посланник {link:nimboya}Нимбойя{/link} отправил свою пику на север, чтобы она встала в одной из этих деревень, увенчанная черепами Сухокожих.]=],
		},
	},
})

Translate("ruRU", "agol-watha-and-shaol-watha", {
	title = "Агол'вата и Шаол'вата",
	aliases = { "Агол'вата", "Шаол'вата" },
	sections = {
		{
			title = "Обзор",
			text = [=[Агол'вата и Шаол'вата — два храма троллей {red:vilebranch-trolls}Порочной Ветви{/red} на северо-востоке Внутренних земель. Там собираются их охотники за скальпами и прорицатели, и оттуда их налетчики выступают против Деревни Сломанного Клыка. После одного такого набега украденные инструменты кузнеца Сломанного Клыка видели возле этих храмов. Для троллей Сломанного Клыка эти два храма — гнезда людоедов, и их охотники возвращаются оттуда с историями, которых не рассказывают юным.]=],
		},
	},
})

Translate("ruRU", "seradane", {
	title = "Серадан",
	sections = {
		{
			title = "Обзор",
			text = [=[Серадан лежит на дальнем северо-востоке Внутренних земель, в высокой лощине за храмами троллей. Там поднимается великое древо. Это одно из немногих мест в мире, где явь соприкасается с {link:emerald-dream}Изумрудным Сном{/link}, и друиды числят его среди четырех таких деревьев {link:azeroth}Азерота{/link}. Зеленые дракониды стерегут его корни, а великие зеленые драконы следят за его кроной. С теми, кто подходит близко, они переговоров не ведут, и ни тролль, ни {link:dwarves}дворф{/link} по доброй воле в их лощину не поднимется.]=],
		},
	},
})

Translate("ruRU", "the-overlook-cliffs", {
	title = "Отвесные скалы",
	sections = {
		{
			title = "Обзор",
			text = [=[Отвесные скалы — высокий восточный край Внутренних земель, где суша отвесно обрывается в море. Водопады низвергаются с холмов в волны, а у самого берега лежат маленькие острова. Пленный тролль из Сухокожих {link:rin-ji}Рин'джи{/link} спрятал на одном из этих островов табличку своего народа. {link:gnomes}Гномы{/link}-инженеры Пиратской бухты однажды выбрали береговую полосу за скалами как безопасное место, куда можно вызвать домой разбитую летающую машину. Старая загадка из далеких краев говорит о сокровище под водой у подножия большого водопада.]=],
		},
	},
})

Translate("ruRU", "falstad-wildhammer", {
	title = "Фалстад Неистовый Молот",
	subtitle = "Верховный тан клана Неистового Молота",
	found = "Крепость Громового Молота, Заоблачный Пик",
	hint = "Поговорите с верховным таном в крепости Заоблачного Пика.",
	allegiance = "Неистовый Молот",
	aliases = { "Фалстад" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фалстад Неистовый Молот — верховный тан {link:dwarves}дворф{/link}ов {red:wildhammer-clan}Неистового Молота{/red}. Из своей крепости на Заоблачном Пике он правит кланом, его наездниками и его грифонами. Терпения у него мало, а память долгая. Пока тролли напирают на его границы, ему не до болтовни, и он говорит об этом прямо. И все же сила клана держится на его суждении, и всякое дело, что приходит на {link:aerie-peak}Заоблачный Пик{/link}, сначала проходит через его чертог.]=],
		},
		{
			title = "Значение",
			text = [=[Фалстад возглавляет единственный клан {link:dwarves}дворф{/link}ов, который не подчиняется королю {link:magni-bronzebeard}Магни Бронзобороду{/link}. Дворфы Неистового Молота — родня {link:ironforge}Стальгорну{/link}, и во {link:second-war}Вторую войну{/link} они летали на стороне {link:alliance}Альянса{/link}. И все же они живут своим умом. Под его началом {link:aerie-peak}Заоблачный Пик{/link} стоит один среди холмов троллей, а его жители настаивают, что не входят в Альянс. Дружба с ними — не договор. Это долг, оплаченный делами, по одному троллю за раз.

Для окрестных земель его правление — разница между рубежом и глушью. {link:trolls}Тролли{/link} Сломанного Клыка зовут его народ грязью и втыкают окровавленные копья в его городе. Тролли Порочной Ветви крадут его грифонов. Слизни Осклизлой скалы стоят между его наездниками и сердцем края. На все это Фалстад отвечает одинаково: дворфы Неистового Молота были здесь прежде и будут здесь после.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он правит Заоблачным Пиком и кланом Неистового Молота как верховный тан.
• Он хранит независимость клана, который по крови союзник {link:dwarves}дворф{/link}ов {link:ironforge}Стальгорн{/link}а, но не связан ни с одним королем.
• Он удерживает свои границы сразу от трех племен троллей.
• Чужаков, которые ищут наездников питомника, он отсылает к своему мастеру грифонов Когтистому Топору.
• Он принимает высших эльфов {link:quel-danil-lodge}Кель'Данил{/link}а как друзей — к ярости троллей Сломанного Клыка.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Предания о войне с кланом Драконьей Пасти рассказывают о наезднике на грифоне из клана Неистового Молота по имени Фалстад, который сражался над {link:grim-batol}Грим Батолом{/link} в годы после Второй войны. Один ли это {link:dwarves}дворф{/link} — тот наездник и верховный тан Заоблачного Пика, — ни одна летопись, к которой обращались для этой записи, прямо не говорит. Мало что написано и о том, как Фалстад стал править своим кланом.]=],
		},
	},
	chapters = {
		{
			title = "Тролли из каждой щели",
			hint = [=[Придите на Заоблачный Пик с поручением от Лиги исследователей.]=],
			text = [=[Дворф, пришедший на {link:aerie-peak}Заоблачный Пик{/link} с вопросом, который задал {link:brohann-caskbelly}Броханн Бочкобрюх{/link} из {link:explorers-league}Лиги исследователей{/link}, застал верховного тана не в настроении принимать гостей. {link:trolls}Тролли{/link} лезли из каждого угла холмов, а у тана на войне мало времени на старые истории о пропавшем наезднике. Фалстад выслушал вопрос, поворчал на чужака, который его задал, и отправил дело туда, где ему место, — к хозяину питомника.]=],
		},
		{
			title = "Дела, а не слова",
			hint = [=[Заслужите уважение дворфов Неистового Молота на Заоблачном Пике.]=],
			text = [=[Под его правлением клан меряет чужака тем, что тот делает. Ожерелья троллей, принесенные в его чертог, и слизни, вычищенные с Осклизлой скалы, — единственный язык дружбы, которому верят {link:dwarves}дворф{/link}ы Неистового Молота. Каждое дело записывается. Со временем те, кто не отступается, видят, что двери Заоблачного Пика открываются перед ними чуть шире.]=],
		},
	},
	mentions = {
		{
			text = [=[«Во {link:the-hinterlands}Внутренние земли{/link}», вопрос от Лиги исследователей]=],
		},
		{
			text = [=[«Укротитель грифонов {link:gryphon-master-talonaxe}Когтистый Топор{/link}»]=],
		},
		{ text = "«Награда за тролльи ожерелья», цена дружбы Неистового Молота" },
		{ text = "«Зачистка Осклизлой скалы»" },
		{ text = "«Последнее послание Неистовому Молоту», копье у его колодца" },
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "мастер грифонов Когтистый Топор", note = "хозяин его питомника" },
		{ id = "fraggar-thundermantle", name = "Фраггар Громовая Мантия", note = "испытывает новых друзей клана" },
		{ id = "brohann-caskbelly", name = "Броханн Бочкобрюх", note = "прислал чужака в его чертог" },
		{ id = "primal-torntusk", name = "предводительница Рваный Клык", note = "ведет троллей, ненавидящих его клан" },
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "король его родни в Стальгорне" },
	},
})

Translate("ruRU", "gryphon-master-talonaxe", {
	title = "Мастер грифонов Когтистый Топор",
	subtitle = "Хозяин грифоньего питомника Заоблачного Пика",
	found = "Грифоний питомник Заоблачного Пика",
	hint = [=[Поднимитесь в питомник Заоблачного Пика и поговорите с его хозяином.]=],
	allegiance = "Неистовый Молот",
	aliases = { "Когтистый Топор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мастер грифонов Когтистый Топор хранит большой питомник Заоблачного Пика. Он знает каждого грифона в стаях клана и каждого наездника, который когда-либо на них летал. Их имена он помнит еще долго после того, как другие забыли, и питает в сердце слабость к {link:explorers-league}Лиге исследователей{/link}, ведь его собственный отец был среди {link:dwarves}дворф{/link}ов, которые первыми раскопали {link:uldaman}Ульдаман{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Грифоны — сила {link:dwarves}дворф{/link}ов Неистового Молота, а Когтистый Топор — их хранитель. Когда теряется грифон, это чувствует весь клан. Когда пропал наследник величайшего грифона питомника, именно Когтистый Топор не знал покоя, пока юнца не нашли. Его история показывает, как тесно судьба дворфов связана с судьбой их зверей.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он обучает грифонов Заоблачного Пика и назначает им наездников.
• Когда-то он дал своего лучшего наездника {link:rhapsody-shindigger}Рапсоди Шиндиггер{/link}а исследователю {link:brohann-caskbelly}Броханну Бочкобрюху{/link} для полета над {link:swamp-of-sorrows}Болотом Печали{/link}.
• Он отпустил этого наездника, когда после того полета тем завладела выпивка.
• Он вел поиски грифона Остроклюва — от клеток Сухокожих до Алтаря Зула.
• Когда все прочие поиски ничего не дали, он обратился к прорицателю из клана Неистового Молота в {link:blasted-lands}Выжженных землях{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Наездник, который упал",
			hint = [=[Узнайте у мастера грифонов, что стало с наездником, которого он отправил с исследователем.]=],
			text = [=[Когтистый Топор вспомнил тот полет сразу. Он послал своего лучшего наездника лететь над болотом вместе с исследователем {link:brohann-caskbelly}Броханн{/link}ом на поиски затонувшего храма. Наездником был {link:rhapsody-shindigger}Рапсоди Шиндиггер{/link}, и никто в питомнике не летал так, как он. Но Рапсоди вернулся из того полета потрясенным и жаждущим, и жажда его только росла. В конце концов хозяину питомника пришлось его отослать.]=],
		},
		{
			title = "Пропавший наследник",
			hint = [=[Обыщите деревни троллей и Алтарь Зула в поисках пропавшего молодого грифона.]=],
			text = [=[Остроклюв, наследник могучейшего грифона питомника, пропал, когда охотился с родителями. Когтистый Топор был уверен, что его забрали тролли. Клетки в деревнях Сухокожих обыскали и нашли пустыми. Следом обыскали {link:the-altar-of-zul}Алтарь Зула{/link}, где тролли Порочной Ветви приносят свои жертвы. Молодого грифона не было и там, и Когтистый Топор не знал, горевать ему или радоваться.]=],
		},
		{
			title = "Перо и прорицатель",
			hint = [=[Отнесите перо из гнезда пропавшего грифона прорицателю в Крепости Стражей Пустоты.]=],
			text = [=[Когда все следы остыли, Когтистый Топор обратился к прорицателю {link:thadius-grimshade}Тадиусу Мрачной Тени{/link}. Тот покинул {link:aerie-peak}Заоблачный Пик{/link} много лет назад в поисках более темных знаний, но Когтистый Топор по-прежнему называл его {link:dwarves}дворф{/link}ом Неистового Молота в душе. Перо из гнезда, где спал молодой грифон, послали в башню прорицателя, чтобы он проследил его нить до хозяина.]=],
		},
		{
			title = "Клетка на утесе",
			hint = [=[Верните домой молодого грифона, которого держат тролли Порочной Ветви.]=],
			text = [=[Гадание Мрачной Тени нашло грифона в клетке высоко на утесе в {link:jintha-alor}Джинта'Алор{/link}е. Ключ висел на поясе мерзкой жрицы {link:vile-priestess-hexx}Хексс{/link}. {link:dwarves}Дворфы{/link} Неистового Молота не могли этого вынести. Жрица пала, клетку открыли, и Остроклюв улетел домой к родителям. Когтистый Топор смотрел, как они хлопочут над своим детенышем, и глаза старого дворфа не были сухи.]=],
		},
	},
	mentions = {
		{ text = "«Укротитель грифонов Когтистый Топор»" },
		{ text = "«{link:rhapsody-shindigger}Рапсоди Шиндиггер{/link}»" },
		{ text = "«Клетки Сухокожих»" },
		{ text = "«{link:the-altar-of-zul}Алтарь Зула{/link}»" },
		{ text = "«{link:thadius-grimshade}Тадиус Мрачная Тень{/link}»" },
		{
			text = [=[«Возвращение во {link:the-hinterlands}Внутренние земли{/link}»]=],
		},
		{ text = "«Спасение Остроклюва»" },
	},
	bonds = {
		{ id = "falstad-wildhammer", name = "Фалстад Неистовый Молот", note = "его верховный тан" },
		{ id = "rhapsody-shindigger", name = "Рапсоди Шиндиггер", note = "некогда его лучший наездник" },
		{ id = "sharpbeak", name = "Остроклюв", note = "пропавший наследник питомника" },
		{ id = "thadius-grimshade", name = "Тадиус Мрачная Тень", note = "дворф Неистового Молота в душе" },
		{ id = "vile-priestess-hexx", name = "мерзкая жрица Хексс", note = "держала ключ от клетки грифона" },
		{ id = "brohann-caskbelly", name = "Броханн Бочкобрюх", note = "одолжил его лучшего наездника" },
	},
})

