	aliases = { "Рапсоди" },
	sections = {
		{
			title = "Обзор",
			text = [=[Рапсоди Шиндиггер был когда-то лучшим наездником на грифонах на Заоблачном Пике. Он летал с исследователем {link:brohann-caskbelly}Броханном Бочкобрюхом{/link} над {link:swamp-of-sorrows}Болотом Печали{/link} в поисках затонувшего храма. После того полета он запил, и питомник с ним расстался. Теперь он держит собственный лагерь-пивоварню и икает на каждой фразе.]=],
