	},
	chapters = {
		{
			title = "Крепкая выпивка",
			hint = "Принесите бывшему наезднику то, что нужно ему для рассказа.",
			text = [=[Трезвым Рапсоди о болоте говорить не желал. Только питье, сваренное из зобов и печени зверей далекого {link:kalimdor}Калимдора{/link}, могло развязать ему язык. Тогда наконец история вышла наружу. Наездник упал в болото, провалился в храм {link:temple-of-atal-hakkar}Атал'ай{/link} и выплыл с реликвией троллей в руке. Храм, который искал {link:brohann-caskbelly}Броханн{/link}, был настоящим.]=],
		},
	},
	mentions = {
		{ text = "«Рапсоди Шиндиггер»" },
