	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "мастер грифонов Когтистый Топор", note = "отставил его" },
		{ id = "brohann-caskbelly", name = "Броханн Бочкобрюх", note = "летал с ним над болотом" },
		{ id = "gilveradin-sunchaser", name = "Гилверадин Ловец Солнца", note = "делит с ним лагерь" },
	},
})

Translate("ruRU", "gilveradin-sunchaser", {
	title = "Гилверадин Ловец Солнца",
	subtitle = "Высший эльф Внутренних земель",
