	sections = {
		{
			title = "Обзор",
			text = [=[Изгнанник Атал'ай был некогда жрецом Атал'ай, секты троллей из затонувшего храма в {link:swamp-of-sorrows}Болоте Печали{/link}. Когда пророк {link:jammal-an-the-prophet}Джаммал'ан{/link} предрек, что призыв бога {link:hakkar}Хаккара{/link} сделает Атал'ай бессмертными, этот жрец призвал к осторожности. За это его назвали неверным и изгнали. Приговор его народа отправил его на север жить среди Сухокожих — участь, которую Атал'ай считают хуже смерти.]=],
		},
		{
			title = "Значение",
			text = [=[Изгнанник — редкий голос сомнения внутри культа бога {link:hakkar}Хаккар{/link}а. Он считает, что пророчество, которое изрек {link:jammal-an-the-prophet}Джаммал'ан{/link}, погубит его народ, и знает обряды призыва достаточно хорошо, чтобы их бояться.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он предупреждал пророка, что пророчество может быть всего лишь обманом.
• Он счел безвредными артефакты Атал'ай, принесенные ему с болота, но предостерег о том, что может сделать обряд, если его завершить.
• Он ищет мести за свое изгнание.]=],
		},
	},
	chapters = {
		{
			title = "Голова пророка",
			hint = "Отомстите за изгнанника пророку, который его изгнал.",
			text = [=[Изгнанник хотел получить голову пророка. Он надеялся, что его народ освободится, когда пророка не станет, и что сам он сможет вернуться домой. Когда дело было сделано, он поблагодарил и предался скорби. Ложные видения, которые видел {link:jammal-an-the-prophet}Джаммал'ан{/link}, уже привели Атал'ай к гибели. Дома, куда он мог бы вернуться, не осталось.]=],
		},
	},
	mentions = {
		{ text = "«Изгнанник Атал'ай»" },
		{ text = "«Возвращение к {link:fel-zerul}Фел'зерул{/link}у»" },
		{ text = "«{link:jammal-an-the-prophet}Джаммал'ан Пророк{/link}»" },
	},
	bonds = {
		{ id = "fel-zerul", name = "Фел'зерул", note = "послал ему артефакты Атал'ай" },
	},
})

