})

Translate("ruRU", "vile-priestess-hexx", {
	title = "Мерзкая жрица Хексс",
	subtitle = "Верховная жрица Порочной Ветви",
	found = "Вершина Джинта'Алора",
	hint = [=[Сразитесь с верховной жрицей, которая правит вершиной Джинта'Алора.]=],
	allegiance = "Порочная Ветвь",
	aliases = { "Хексс" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мерзкая жрица Хексс — верховная жрица троллей {red:vilebranch-trolls}Порочной Ветви{/red}. Она правит вершиной {link:jintha-alor}Джинта'Алор{/link}а со своей отборной стражей Аман'заси. Ее темные плетения наполняют сосуды с оскверненной кровью по всему городу, и через них сила кровавого бога {link:hakkar}Хаккара{/link} приводит ее народ в безумную, не знающую смерти ярость.]=],
		},
		{
			title = "Значение",
			text = [=[Хексс — причина того, что Порочная Ветвь больше, чем дикое племя. Через нее эти тролли стали слугами кровавого бога и берут пленников для жертвы из каждого народа Внутренних земель. От ее власти страдают равно и {link:dwarves}дворф{/link}ы, и тролли. И {link:aerie-peak}Заоблачный Пик{/link}, и {link:revantusk-village}Деревня Сломанного Клыка{/link} назначили цену за ее голову. {link:trolls}Тролли{/link} Сломанного Клыка предупреждают, что, даже если она падет, на ее место встанет другая.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она готовила старейшину Рваного Клыка из племени Сломанного Клыка в жертву кровавому богу.
• Она держала ключ от клетки, где сидел Остроклюв, молодой грифон с Заоблачного Пика.
• Она наделила троллей Порочной Ветви силой оскверненной крови безликого бога.
• Она командует Аман'заси, отборной стражей {link:jintha-alor}Джинта'Алор{/link}а.]=],
		},
	},
	chapters = {
		{
			title = "Жрица кровавого бога",
			hint = "Сломите силу оскверненных сосудов Джинта'Алора.",
			text = [=[{link:trolls}Тролли{/link} Сломанного Клыка узнали, где Порочная Ветвь берет свою силу. По всему {link:jintha-alor}Джинта'Алор{/link}у стояли сосуды с оскверненной кровью, оплетенные магией жрицы и наполненные силой бога {link:hakkar}Хаккар{/link}а. Когда сосуды были украдены и очищены, безумие Порочной Ветви ослабло. Оно не кончилось.]=],
		},
		{
			title = "Падение жрицы",
			hint = "Предайте мерзкую жрицу правосудию.",
			text = [=[По приказу, который отдала предводительница {link:primal-torntusk}Рваный Клык{/link}, была обещана награда за смерть жрицы и ее стражей Аман'заси. {link:dwarves}Дворфы{/link} Заоблачного Пика тоже хотели ее смерти, ведь у нее был ключ от клетки молодого грифона. Жрица пала на вершине своего города. Порочная Ветвь пошатнулась от удара, а ее враги знали, что без вождя она останется недолго.]=],
		},
	},
	mentions = {
		{
			text = [=[«{link:elder-torntusk}Старейшина Рваный Клык{/link} похищен!»]=],
		},
		{ text = "«Темные сосуды»" },
		{ text = "«Разыскивается: мерзкая жрица Хексс и ее прислужники»" },
		{
			text = [=[«Возвращение во {link:the-hinterlands}Внутренние земли{/link}», слово прорицателя]=],
		},
		{ text = "«Спасение Остроклюва»" },
	},
	bonds = {
		{ id = "primal-torntusk", name = "предводительница Рваный Клык", note = "назначила цену за ее голову" },
		{ id = "elder-torntusk", name = "старейшина Рваный Клык", note = "ее пленник" },
		{ id = "sharpbeak", name = "Остроклюв", note = "ее пленник" },
		{ id = "hitah-ya-the-keeper", name = "хранительница Хита'йя", note = "держит ключи от ее пленников" },
	},
})

