Translate("ruRU", "shadra", {
	title = "Шадра",
	subtitle = "Королева яда",
	found = "Вызывается у алтаря Шадра'Алора",
	hint = [=[Узнайте истинное имя паучьей богини Сухокожих и произнесите его у ее алтаря.]=],
