	sections = {
		{
			title = "Обзор",
			text = [=[Шадра — паучья богиня троллей племени {link:witherbark-trolls}Сухокожих{/link}. Они зовут ее Королевой яда, и от нее исходит самый сильный яд, какой они знают. Среди своих почитателей она не ходит. Она является, только когда ее истинное имя читают вслух у ее алтаря в {link:shadra-alor}Шадра'Алор{/link}е, а имя это так отягощено силой, что мудрые произносят его лишь шепотом.]=],
		},
