			title = "Значение",
			text = [=[Шадра — сердце веры Сухокожих. Ее имя было давным-давно начертано на табличке в городе троллей {red:zul-farrak}Зул'Фарраке{/red}, далеко за морем. {link:royal-apothecary-society}Королевское фармацевтическое общество{/link}, которое служит Отрекшимся, жаждет ее яда превыше всех прочих.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она дает свой яд Сухокожим, которые хранят его в бутылях в своих деревнях.
• Ее вызвали к ее алтарю заклинанием призыва, которое составил {link:master-gadrin}мастер Гадрин{/link} из племени Черного Копья.]=],
		},
	},
	chapters = {
		{
			title = "Королева яда",
			hint = "Вызовите паучью богиню в Шадра'Алоре.",
			text = [=[{link:apothecary-lydon}Аптекарь Лайдон{/link} с {link:tarren-mill}Мельницы Таррен{/link} хотел самого свежего яда Сухокожих, и обычный паук для этого не годился. {link:master-gadrin}Мастер Гадрин{/link} знал, откуда этот яд берется. С таблички в Зул'Фарраке пришло ее истинное имя, а от мастера — пергамент, способный ее призвать. У алтаря {link:shadra-alor}Шадра'Алор{/link}а слова были прочитаны, и Королева яда ответила. Ее яд ушел на Мельницу Таррен, а оттуда — в {link:the-apothecarium}Аптекариум{/link} {link:undercity}Подгород{/link}а.]=],
		},
	},
	mentions = {
		{ text = "«Бутылочки с ядом»" },
		{ text = "«Неповрежденный ядовитый мешочек»" },
		{ text = "«{link:shadow-council}Совет{/link} мастера Гадрина»" },
		{ text = "«Паучий бог»" },
		{ text = "«Призыв Шадры»" },
		{ text = "«Яд для {link:undercity}Подгород{/link}а»" },
	},
	bonds = {
		{ id = "master-gadrin", name = "мастер Гадрин", note = "написал заклинание, которое ее призывает" },
		{ id = "apothecary-lydon", name = "аптекарь Лайдон", note = "искал ее яд" },
		{ id = "master-apothecary-faranell", name = "главный аптекарь Фаранелл", note = "получил ее яд" },
	},
})

Translate("ruRU", "primal-torntusk", {
